import{_ as e,o as a,c as s,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const c=JSON.parse('{"title":"Amp","description":"","frontmatter":{},"headers":[],"relativePath":"synths/AMP.md","filePath":"synths/AMP.md"}'),n={name:"synths/AMP.md"};function r(d,t,h,i,l,p){return a(),s("div",null,[...t[0]||(t[0]=[o('<h1 id="amp" tabindex="-1">Amp <a class="header-anchor" href="#amp" aria-label="Permalink to &quot;Amp&quot;">​</a></h1><p>The Amp, or VCA, is the last part of every note before the instrument&#39;s effects: it sets how loud the note sounds, opened by Env 1 as a key is played and closed as Env 1 falls. Every voice has its own, as every voice of a polysynth has its own VCA, and it always closes when its note ends, so that no sound is left droning. It sits on the Amp tab, between the Filter and FX tabs, in the order the sound flows: Oscillators, Filter, Amp, FX.</p><h2 id="volume" tabindex="-1">Volume <a class="header-anchor" href="#volume" aria-label="Permalink to &quot;Volume&quot;">​</a></h2><p>The Amp tab&#39;s Volume, under its Type, is the whole instrument&#39;s level, from 0% to 150%, 90% unless set. It dims or lifts everything the instrument plays, after its effects, as a mixer&#39;s fader does, so that one instrument can sit under the others without changing how hard its notes drive the Amp or the effects.</p><h2 id="swappable-amps" tabindex="-1">Swappable Amps <a class="header-anchor" href="#swappable-amps" aria-label="Permalink to &quot;Swappable Amps&quot;">​</a></h2><p>An amp looks like the plainest part of a synthesizer, and on paper it only turns the sound up and down. In a real instrument it is a circuit with a character of its own. The discrete transistor amps of the classic monosynths round off loud notes and leak a little of the sound when shut, part of those instruments&#39; warmth and drone. The chip amps of later polysynths and modular synthesizers open along a steeper curve and saturate more softly. Here the Amp&#39;s Type chooses the circuit, as an envelope&#39;s type chooses its shape, so that an engine&#39;s oscillator and filter can be heard through another engine&#39;s amp.</p><p>Each type saturates the signal itself, so that a loud note, a hot signal coming from the filter and a high setting all push it alike, as on the hardware. A quiet note passes through almost untouched.</p><p>Every type has a Response, how Env 1 opens it. At 0% the loudness follows the envelope straight. Toward 100% it follows an exponential curve, so that a note opens later and falls away faster, snappier and more percussive.</p><p>Each engine&#39;s preset chooses its Amp: Asheville starts on Transistor, the others on Clean.</p><h2 id="clean" tabindex="-1">Clean <a class="header-anchor" href="#clean" aria-label="Permalink to &quot;Clean&quot;">​</a></h2><p>A perfect amp, as the built-in synths have always had: at its defaults the note comes out exactly as Env 1 shapes it. Its Character warms it. Turned up, it rounds off and gently saturates the loudest moments, as warmer amps do, leaving the quiet ones alone.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>Response</td><td>0 to 100%</td><td>How Env 1 opens it, from linear to exponential.</td></tr><tr><td>Character</td><td>0 to 100%</td><td>How warmly the loudest moments are rounded off; 0% is perfectly clean.</td></tr></tbody></table><h2 id="transistor" tabindex="-1">Transistor <a class="header-anchor" href="#transistor" aria-label="Permalink to &quot;Transistor&quot;">​</a></h2><p>The discrete amp of the classic monosynths. It warms and squashes the loudest notes, its Drive pushing it harder, and its Bleed lets a little of the sound through when it is shut, the faint drone under a held note&#39;s silence on those instruments.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>Response</td><td>0 to 100%</td><td>How Env 1 opens it, from linear to exponential.</td></tr><tr><td>Drive</td><td>0 to 100%</td><td>How hard the loudest notes are pushed into saturation.</td></tr><tr><td>Bleed</td><td>0 to 100%</td><td>How much leaks through when it is shut, at most 40 dB down.</td></tr></tbody></table><h2 id="ota" tabindex="-1">OTA <a class="header-anchor" href="#ota" aria-label="Permalink to &quot;OTA&quot;">​</a></h2><p>The chip amp of the polysynths and modular synthesizers. It opens along a steeper curve by default and saturates rounder than the Transistor, its Drive pushing it harder.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>Response</td><td>0 to 100%</td><td>How Env 1 opens it, from linear to exponential.</td></tr><tr><td>Drive</td><td>0 to 100%</td><td>How hard the loudest notes are pushed into saturation.</td></tr></tbody></table><h2 id="low-pass-gate" tabindex="-1">Low-pass Gate <a class="header-anchor" href="#low-pass-gate" aria-label="Permalink to &quot;Low-pass Gate&quot;">​</a></h2><p>A vactrol in the amp&#39;s place, the note&#39;s last stage: one light-sensitive cell that closes the sound and darkens it at once, as a struck or plucked thing fades, the classic pluck and bonk of modular synthesizers. It is the same gate as the Filter tab&#39;s (<a href="./FILTERS#low-pass-gate">Filters</a>), with the same settings, but here it always closes when its note ends: its Trigger is Trigger, a short flash at each note; Gate, lit while the note is held; or Env 1, whose level it follows through its cell. Its Mode adds VCA, the loudness alone.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>Trigger</td><td>Trigger, Gate, Env 1</td><td>What lights the cell.</td></tr><tr><td>Trigger time</td><td>0.5 to 50 ms</td><td>How long the flash lasts, with Trigger.</td></tr><tr><td>Mode</td><td>VCA, Lowpass, Both</td><td>Loudness alone, the cutoff alone, or both together.</td></tr><tr><td>Signal</td><td>Oscillator, Ping, Both</td><td>The sound coming in, a short pulse each note, or both.</td></tr><tr><td>Ping time</td><td>0.5 to 20 ms</td><td>How long the ping lasts, with a Ping.</td></tr><tr><td>Resonance</td><td>0 to 100%</td><td>How much the Lowpass mode rings.</td></tr><tr><td>Open</td><td>100 Hz to 16 kHz</td><td>The cutoff fully lit.</td></tr><tr><td>Key track</td><td>0 to 100%</td><td>How far the cutoff follows the note.</td></tr><tr><td>Response</td><td>0 to 100%</td><td>How fast the cell is, from fast to lazy.</td></tr><tr><td>Memory</td><td>0 to 100%</td><td>How much of the last glow carries into the next note.</td></tr><tr><td>Age</td><td>0 to 100%</td><td>An old cell: dimmer and slower.</td></tr><tr><td>Stability</td><td>0 to 100%</td><td>How alike each note is.</td></tr></tbody></table><p><a href="./../SYNTHS">Synths</a> lists every part of the built-in instruments.</p>',22)])])}const m=e(n,[["render",r]]);export{c as __pageData,m as default};
